// scheduleDeploymentRequest parses the Definition of a scheduled action and returns the
// embedded CreateDeploymentRequest, or nil if it cannot be determined.
func scheduleDeploymentRequest(s apitype.ScheduledAction) *apitype.CreateDeploymentRequest {
	if len(s.Definition) == 0 {
