// definition and timing fields.
func scheduleKindOf(s apitype.ScheduledAction) string {
	op := scheduleOperation(s)
	switch {
	case op == apitype.Destroy && s.ScheduleOnce != "":
		return scheduleKindTTL
	case op == apitype.DetectDrift:
		return scheduleKindDrift
	default:
		return scheduleKindRaw
	}
}

// scheduleTiming returns a human-readable representation of when a scheduled action runs.
func scheduleTiming(s apitype.ScheduledAction) string {
	if s.ScheduleCron != "" {
		return s.ScheduleCron
	}
	if s.ScheduleOnce != "" {
		return "Once"
	}
