// runStackScheduleList fetches all schedules for the stack and renders them. When count > 0
// and count < len(schedules), the list is truncated to the first count items before rendering.
func runStackScheduleList(
	ctx context.Context,
	w io.Writer,
	factory stackScheduleListClientFactory,
	stackFlag string,
	count int,
	render scheduleListRenderFunc,
) error {
	c, stackID, err := factory(ctx, stackFlag)
	if err != nil {
		return err
	}

	schedules, err := c.ListStackSchedules(ctx, stackID)
	if err != nil {
		return fmt.Errorf("listing stack schedules: %w", err)
	}

	if count > 0 && count < len(schedules) {
		schedules = schedules[:count]
	}

