}

func scheduleListRenderer(output string) (scheduleListRenderFunc, error) {
	switch output {
	case "", "default", "table":
		return renderScheduleListTable, nil
	case "json":
		return renderScheduleListJSON, nil
	default:
		return nil, fmt.Errorf("invalid --output value %q: expected \"default\", \"table\", or \"json\"", output)
	}
}

func renderScheduleListTable(w io.Writer, schedules []apitype.ScheduledAction) error {
	if len(schedules) == 0 {
		fmt.Fprintln(w, "No scheduled actions configured for this stack.")
		return nil
	}

	t := table.NewWriter()
	t.SetOutputMirror(w)
	t.SetStyle(table.StyleLight)
	t.AppendHeader(table.Row{"ID", "TYPE", "SETTINGS", "SCHEDULE", "NEXT RUN", "LAST RUN", "CREATED"})

	for _, s := range schedules {
		summary := toScheduleSummary(s)
		lastRun := summary.LastRun
		if lastRun == "" {
			lastRun = "(never)"
		}
		t.AppendRow(table.Row{
			summary.ID,
			summary.Type,
			summary.Settings,
			summary.Schedule,
			summary.NextRun,
			lastRun,
			summary.Created,
		})
	}

	t.Render()
	return nil
}

func renderScheduleListJSON(w io.Writer, schedules []apitype.ScheduledAction) error {
	items := make([]scheduleSummary, 0, len(schedules))
	for _, s := range schedules {
		items = append(items, toScheduleSummary(s))
	}
	enc := json.NewEncoder(w)
	enc.SetEscapeHTML(false)
	enc.SetIndent("", "  ")
	return enc.Encode(struct {
		Schedules []scheduleSummary `json:"schedules"`
	}{Schedules: items})
}
